begin;
create function pg_temp.check_that(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.reject_config_history() returns trigger language plpgsql as $$begin if new.action='luma.configuration.saved' and new.request->>'configHash' = current_setting('test.reject_hash',true) then raise exception 'fixture history outage';end if;return new;end;$$;
create trigger local_config_history_failure before insert on public.shared_action_events for each row execute function pg_temp.reject_config_history();
do $$
declare property uuid:=gen_random_uuid();actor uuid;calendar uuid:=gen_random_uuid();request_id uuid:=gen_random_uuid();revision text;result jsonb;before_state jsonb;change jsonb;event_count integer;other uuid:=gen_random_uuid();lead uuid:=gen_random_uuid();
begin
 select id into actor from public.profiles where org_id='22222222-2222-2222-2222-222222222222' limit 1;
 insert into public.properties(id,org_id,name,settings) values(property,'22222222-2222-2222-2222-222222222222','Configuration transaction fixture','{}');
 perform pg_temp.check_that(not has_function_privilege('anon','public.read_luma_configuration(uuid)','execute'),'anonymous cannot read private configuration');
 perform pg_temp.check_that(not has_function_privilege('authenticated','public.save_recorded_luma_configuration(uuid,uuid,uuid,text,jsonb,text)','execute'),'browser role cannot bypass service authentication');
 result:=public.read_luma_configuration(property);revision:=result->>'revision';
 perform pg_temp.check_that(result->'config'='null'::jsonb and length(revision)=64,'read preserves an absent configuration');
 perform pg_temp.check_that(not exists(select 1 from public.lumaleasing_config where property_id=property),'read does not initialize');
 result:=public.save_recorded_luma_configuration(property,other,request_id,'initialize','{}',revision);
 perform pg_temp.check_that(result->>'state'='forbidden','wrong actor is denied');
 result:=public.save_recorded_luma_configuration(property,actor,request_id,'initialize','{}',revision);
 perform pg_temp.check_that(result->>'state'='applied' and result->>'actionEventId'=request_id::text,'initialize commits a recorded decision');
 perform pg_temp.check_that(result->'config'->'timezone'='null'::jsonb,'initialize does not invent timezone');
 perform pg_temp.check_that((select count(*)=1 from public.shared_action_events where property_id=property and action='luma.configuration.created'),'initialize records one event');
 result:=public.save_recorded_luma_configuration(property,actor,request_id,'initialize','{}',revision);
 perform pg_temp.check_that(result->>'state'='replayed','lost initialization response replays');
 perform pg_temp.check_that((select count(*)=1 from public.lumaleasing_config where property_id=property),'replay does not duplicate configuration');
 perform pg_temp.check_that((select h.before_state::text||h.after_state::text||h.request::text not like '%luma_%' from public.shared_action_events h where h.id=request_id),'history excludes widget API key');
 result:=public.save_recorded_luma_configuration(property,actor,request_id,'save','{"widget_name":"forged reuse"}',revision);
 perform pg_temp.check_that(result->>'state'='request_conflict','request_id cannot be reused for another operation');
 insert into public.agent_calendars(id,property_id,profile_id,google_email,account_email,provider,timezone,access_token,refresh_token,token_expires_at,sync_enabled,token_status)
 values(calendar,property,actor,'fixture@example.invalid','fixture@example.invalid','google',null,'fixture-secret-access','fixture-secret-refresh','2099-01-01',true,'healthy');
 revision:=public.read_luma_configuration(property)->>'revision';
 change:='{"widget_name":"Saved assistant","tour_duration_minutes":45,"tour_buffer_minutes":0,"timezone":"America/New_York","business_hours":{"monday":{"start":"09:00","end":"17:00"},"tuesday":null},"floor_plans_url":"https://example.com/plans","availability_url":"https://example.com/homes","agent_avatar_url":"https://example.com/avatar.png"}';
 request_id:=gen_random_uuid();result:=public.save_recorded_luma_configuration(property,actor,request_id,'save',change,revision);
 perform pg_temp.check_that(result->>'state'='applied','save succeeds');
 perform pg_temp.check_that((select widget_name='Saved assistant' and floor_plans_url='https://example.com/plans' and availability_url='https://example.com/homes' and agent_avatar_url='https://example.com/avatar.png' from public.lumaleasing_config where property_id=property),'all editable widget fields persist');
 perform pg_temp.check_that((select settings->>'timezone'='America/New_York' from public.properties where id=property),'property timezone aligns');
 perform pg_temp.check_that((select timezone='America/New_York' and tour_duration_minutes=45 and buffer_minutes=0 and working_hours->'mon'->>'enabled'='true' and working_hours->'tue'->>'enabled'='false' from public.agent_calendars where id=calendar),'calendar hours duration zero buffer and timezone commit');
 perform pg_temp.check_that((select evidence='server_confirmed' and phase='succeeded' and not training_eligible and product='lumaleasing' and after_state::text not like '%fixture-secret%' from public.shared_action_events where id=request_id),'trusted action remains training ineligible and excludes tokens');
 result:=public.save_recorded_luma_configuration(property,actor,request_id,'save',change,revision);
 perform pg_temp.check_that(result->>'state'='replayed','lost settings response replays without a new event');
 perform pg_temp.check_that((select count(*)=1 from public.shared_action_events where id=request_id),'settings replay has one event');
 result:=public.save_recorded_luma_configuration(property,actor,gen_random_uuid(),'save','{"widget_name":"stale draft"}',revision);
 perform pg_temp.check_that(result->>'state'='stale_configuration','stale draft is held');
 perform pg_temp.check_that((select widget_name='Saved assistant' from public.lumaleasing_config where property_id=property),'stale draft cannot overwrite');
 revision:=public.read_luma_configuration(property)->>'revision';
 update public.agent_calendars set buffer_minutes=10 where id=calendar;
 result:=public.save_recorded_luma_configuration(property,actor,gen_random_uuid(),'save','{"widget_name":"stale calendar"}',revision);
 perform pg_temp.check_that(result->>'state'='stale_configuration','calendar changes invalidate a stale widget form');
 revision:=public.read_luma_configuration(property)->>'revision';
 result:=public.save_recorded_luma_configuration(property,actor,gen_random_uuid(),'save','{"api_key":"injected"}',revision);
 perform pg_temp.check_that(result->>'state'='invalid_configuration','unsupported secret mutation is rejected');
 result:=public.save_recorded_luma_configuration(property,actor,gen_random_uuid(),'save','{"timezone":"Wrong/Timezone"}',revision);
 perform pg_temp.check_that(result->>'state'='invalid_timezone','invalid timezone is rejected');
 result:=public.save_recorded_luma_configuration(property,actor,gen_random_uuid(),'save','{"business_hours":{"monday":{"start":"19:00","end":"08:00"}}}',revision);
 perform pg_temp.check_that(result->>'state'='invalid_hours','reversed working hours are rejected');
 before_state:=public.luma_configuration_snapshot(property);select count(*) into event_count from public.shared_action_events where property_id=property;
 change:='{"widget_name":"Rollback fixture","timezone":"UTC","tour_buffer_minutes":20}';
 perform set_config('test.reject_hash',encode(sha256(convert_to(change::text,'UTF8')),'hex'),true);
 begin
  perform public.save_recorded_luma_configuration(property,actor,gen_random_uuid(),'save',change,revision);
  raise exception 'Expected history failure';
 exception when others then if sqlerrm<>'fixture history outage' then raise;end if;end;
 perform pg_temp.check_that(public.luma_configuration_snapshot(property)=before_state,'action failure rolls back widget property and calendar');
 perform pg_temp.check_that((select count(*)=event_count from public.shared_action_events where property_id=property),'failed transaction leaves no partial decision');
 insert into public.leads(id,property_id,first_name,source) values(lead,property,'Legacy fixture','manual');
 insert into public.tours(property_id,lead_id,tour_date,tour_time,status) values(property,lead,current_date+10,'10:00','scheduled');
 result:=public.save_recorded_luma_configuration(property,actor,gen_random_uuid(),'save','{"timezone":"UTC"}',revision);
 perform pg_temp.check_that(result->>'state'='legacy_timezone_review','unqualified legacy tours prevent timezone reinterpretation');
 perform pg_temp.check_that(public.luma_configuration_snapshot(property)=before_state,'legacy review does not change current settings');
end; $$;
rollback;
